KLIN = [('CaCl', 'CaCl₂', 'Ca²⁺ i dwa Cl⁻ — suma ładunków musi wynosić 0.'), ('Al₃(SO₄)₂', 'Al₂(SO₄)₃', 'Krzyżujemy ładunki: Al³⁺ → indeks 3 przy SO₄, SO₄²⁻ → indeks 2 przy Al.'), ('„siarczan sodu” dla Na₂SO₃', 'siarczan(IV) sodu', 'Na₂SO₄ to siarczan(VI); trzeba podać wartościowość siarki.'), ('chlorek żelaza dla FeCl₃', 'chlorek żelaza(III)', 'Żelazo ma zmienną wartościowość — podajemy ją.'), ('Cu + ZnSO₄ → CuSO₄ + Zn', 'brak reakcji', 'Cu stoi w szeregu aktywności za Zn — nie wypiera go.'), ('NaCl + KNO₃ → NaNO₃ + KCl (zachodzi)', 'nie zachodzi — wszystkie produkty rozpuszczalne', 'Bez osadu, gazu lub słabego elektrolitu jony tylko się mieszają.'), ('AgCl → Ag⁺ + Cl⁻ (dysocjacja w wodzie)', 'AgCl praktycznie nie dysocjuje', 'AgCl jest nierozpuszczalny (N) — zostaje osadem.'), ('jonowo: Ag⁺ + NO₃⁻ → AgNO₃', 'Ag⁺ + Cl⁻ → AgCl↓', 'Azotany są rozpuszczalne — NO₃⁻ to jon obserwator.'), ('„roztwory soli zawsze mają pH 7”', 'zależy od soli (hydroliza)', 'Na₂CO₃ — zasadowy, NH₄Cl — kwasowy.'), ('wapno palone = Ca(OH)₂', 'wapno palone = CaO, gaszone = Ca(OH)₂', 'CaO + H₂O → Ca(OH)₂ (gaszenie).')]
