S.append(sec(11, 'Klinika błędów', kl))

def lvl(t, qs, ans, start):
    return '<h3>%s</h3><div class="card"><ol start="%d">%s</ol><details class="answer"><summary>Pokaż odpowiedzi</summary><ol start="%d">%s</ol></details></div>\n' % (t, start, ''.join('<li>%s</li>' % q for q in qs), start, ''.join('<li>%s</li>' % a for a in ans))
EX = lvl('Poziom A — podstawa', ['Napisz wzory: chlorek magnezu, siarczan(VI) glinu, azotan(V) wapnia, fosforan(V) sodu.', 'Nazwij: K₂CO₃, FeCl₂, Fe₂(SO₄)₃, CuS.', 'Zapisz dysocjację: Na₂SO₄, Al(NO₃)₃, K₃PO₄.', 'Odczytaj z tabeli: czy rozpuszczalne są AgCl, Na₂CO₃, BaSO₄, CaCO₃?'],
         ['MgCl₂, Al₂(SO₄)₃, Ca(NO₃)₂, Na₃PO₄.', 'węglan potasu, chlorek żelaza(II), siarczan(VI) żelaza(III), siarczek miedzi(II).', 'Na₂SO₄ → 2 Na⁺ + SO₄²⁻; Al(NO₃)₃ → Al³⁺ + 3 NO₃⁻; K₃PO₄ → 3 K⁺ + PO₄³⁻.', 'AgCl — N, Na₂CO₃ — R, BaSO₄ — N, CaCO₃ — N.'], 1)
EX += lvl('Poziom B — trening', ['Zaproponuj 3 sposoby otrzymania MgCl₂ — zapisz równania.', 'Uzupełnij: Zn + CuSO₄ → ? ; Cu + AgNO₃ → ? ; Cu + FeSO₄ → ?', 'Zapisz cząsteczkowo i jonowo (skrócono): BaCl₂ + K₂SO₄.', 'Które pary roztworów dadzą osad: (a) NaCl + AgNO₃, (b) KNO₃ + NaCl, (c) CuCl₂ + NaOH?'],
         ['Mg + 2 HCl → MgCl₂ + H₂↑; MgO + 2 HCl → MgCl₂ + H₂O; Mg(OH)₂ + 2 HCl → MgCl₂ + 2 H₂O (lub Mg + Cl₂ → MgCl₂).', 'ZnSO₄ + Cu; Cu(NO₃)₂ + 2 Ag; brak reakcji.', 'BaCl₂ + K₂SO₄ → BaSO₄↓ + 2 KCl; Ba²⁺ + SO₄²⁻ → BaSO₄↓.', '(a) tak — AgCl; (b) nie; (c) tak — Cu(OH)₂.'], 5)
EX += lvl('Poziom C — ambitny', ['Jak rozróżnić roztwory NaCl, Na₂SO₄ i Na₂CO₃, mając HCl, BaCl₂ i AgNO₃? Zaplanuj kolejność.', 'Oblicz masę osadu AgCl, który powstanie z 5,85 g NaCl (nadmiar AgNO₃).', 'Wyjaśnij, dlaczego woda twarda daje kamień kotłowy. Zapisz równanie.'],
         ['HCl: musuje tylko Na₂CO₃. Do pozostałych BaCl₂: biały osad — Na₂SO₄. Ostatni z AgNO₃ — biały osad AgCl — NaCl.', 'n(NaCl) = 5,85 / 58,44 ≈ 0,1 mol → n(AgCl) = 0,1 mol → m = 0,1 · 143,32 ≈ 14,3 g.', 'Ca(HCO₃)₂ → CaCO₃ + H₂O + CO₂ — przy ogrzewaniu wytrąca się nierozpuszczalny CaCO₃.'], 8)
EX += lvl('Poziom D — LO rozszerzone', ['Przewidź odczyn: K₂CO₃, NH₄NO₃, KCl, CH₃COOK. Zapisz równania hydrolizy.', 'Dlaczego w zapisie jonowym CaCO₃ + 2 HCl CaCO₃ zostaje w postaci cząsteczkowej?'],
         ['K₂CO₃ — zasadowy (CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻); NH₄NO₃ — kwasowy (NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺); KCl — obojętny; CH₃COOK — zasadowy.', 'CaCO₃ jest nierozpuszczalny (N) — w roztworze nie występuje jako jony: CaCO₃ + 2 H⁺ → Ca²⁺ + H₂O + CO₂↑.'], 11)
S.append(sec(12, 'Ćwiczenia', EX + adv('Iloczyn rozpuszczalności i efekt wspólnego jonu', '<p>Dla osadu MₐXᵦ: K<sub>sp</sub> = [M]ᵃ[X]ᵇ (np. AgCl: K<sub>sp</sub> = 1,77·10⁻¹⁰ → rozpuszczalność s = √K<sub>sp</sub> ≈ 1,33·10⁻⁵ mol/dm³). Osad wytrąca się, gdy iloczyn stężeń jonów przekroczy K<sub>sp</sub>. Dodatek wspólnego jonu (np. NaCl do roztworu nad AgCl) zmniejsza rozpuszczalność; z kolei tworzenie kompleksów zwiększa ją (AgCl rozpuszcza się w NH₃: AgCl + 2 NH₃ → [Ag(NH₃)₂]⁺ + Cl⁻).</p>')))

